import{_ as t,o as e,c as r,a as o}from"./chunks/framework.Dj-71DD2.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"md/09-音频&视频批处理/150-根据音视频时长移动或复制文件到相应文件夹归类-UI.md","filePath":"md/09-音频&视频批处理/150-根据音视频时长移动或复制文件到相应文件夹归类-UI.md"}'),n={name:"md/09-音频&视频批处理/150-根据音视频时长移动或复制文件到相应文件夹归类-UI.md"};function i(s,a,p,l,_,h){return e(),r("div",null,[...a[0]||(a[0]=[o('<h2 id="_150-根据音视频时长移动或复制文件到相应文件夹归类-ui" tabindex="-1">150-根据音视频时长移动或复制文件到相应文件夹归类-UI <a class="header-anchor" href="#_150-根据音视频时长移动或复制文件到相应文件夹归类-ui" aria-label="Permalink to &quot;150-根据音视频时长移动或复制文件到相应文件夹归类-UI&quot;">​</a></h2><blockquote><p>作者：极致办公 / 微信：reset201901</p></blockquote><p><img src="https://s2.loli.net/2024/11/02/tK9T7jxLcuv5rUk.png" alt="image"></p><h2 id="_1、程序用环境及相关说明" tabindex="-1">1、程序用环境及相关说明 <a class="header-anchor" href="#_1、程序用环境及相关说明" aria-label="Permalink to &quot;1、程序用环境及相关说明&quot;">​</a></h2><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统<br> 注意事项：win32位系统以及mac系统需要额外定制开发</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><h2 id="_2、程序说明" tabindex="-1">2、程序说明 <a class="header-anchor" href="#_2、程序说明" aria-label="Permalink to &quot;2、程序说明&quot;">​</a></h2><p>ffmpeg文件夹和程序必须放在同一文件夹下，<strong>如下图所示</strong></p><p><img src="https://s2.loli.net/2024/10/20/Rz7MYE4JS61ZGyh.png" alt="image-20241020222439229"></p><p>批量根据指定的时长区间筛选音视频文件，并将符合条件的文件按照操作类型（移动或复制）到按照区间自动创建的文件夹内。</p><p>支持处理子文件夹下音视频，会在每个子文件夹下创建对应的文件夹移动或复制进去</p><p><strong>效果图演示：</strong></p><p><img src="https://s2.loli.net/2024/10/20/bkQrsOa9Zq2XhMi.png" alt="image-20241020222416228"></p><h2 id="_3、使用场景例子展示" tabindex="-1">3、使用场景例子展示 <a class="header-anchor" href="#_3、使用场景例子展示" aria-label="Permalink to &quot;3、使用场景例子展示&quot;">​</a></h2><p>比如A文件夹下有文件，E、F、D....等子文件夹也有文件，只需要输入A文件夹路径并设定时长区间（例如最小时长为10秒，最大时长为100秒），选择移动或复制操作，程序会在A文件夹及其子文件夹中筛选符合时长要求的音视频文件，将它们移动或复制到A文件夹中自动创建的“10-100s”文件夹内，保持原有文件夹结构。</p><h2 id="_4、程序截图" tabindex="-1">4、程序截图 <a class="header-anchor" href="#_4、程序截图" aria-label="Permalink to &quot;4、程序截图&quot;">​</a></h2><p><img src="https://s2.loli.net/2024/10/20/t5R1JxC3blVOLau.png" alt="image-20241020191837479"></p><h2 id="_5、视频演示" tabindex="-1">5、视频演示 <a class="header-anchor" href="#_5、视频演示" aria-label="Permalink to &quot;5、视频演示&quot;">​</a></h2><iframe src="#" width="50%" height="80%"></iframe><h2 id="_6、友情提示" tabindex="-1">6、友情提示 <a class="header-anchor" href="#_6、友情提示" aria-label="Permalink to &quot;6、友情提示&quot;">​</a></h2><p><strong>正式使用前请先测试/备份原文件，然后再大批量使用，以免造成不可逆损失。</strong></p><h2 id="_7、win-mac程序定制说明" tabindex="-1">7、win/mac程序定制说明 <a class="header-anchor" href="#_7、win-mac程序定制说明" aria-label="Permalink to &quot;7、win/mac程序定制说明&quot;">​</a></h2><blockquote><p>程序定制微信：reset201901</p><p>1、明确自身需求，直入主题，简要描述；</p><p>2、我第一步想要怎样，第二步想要怎样...；</p><p>3、最终想要的结果是什么样的，自己能够清晰的描述出来,</p><p>4、最好是用txt文档将以上需求写清楚，或者录制视频将需求讲述清楚；</p><p>5、提供需要做测试的文件给我们，如果文件不便展示，可以创建一个txt文件将文件名后缀.txt修改为你同类型的文件即可。</p></blockquote><h2 id="_8、本工具下载地址" tabindex="-1"><em>8、本工具下载地址</em> <a class="header-anchor" href="#_8、本工具下载地址" aria-label="Permalink to &quot;*8、本工具下载地址*&quot;">​</a></h2><p>下载地址：<a href="https://www.softbangong.top/?id=152" target="_blank" rel="noreferrer">https://www.softbangong.top/?id=152</a></p>',24)])])}const m=t(n,[["render",i]]);export{d as __pageData,m as default};
